def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 2:
            bid = DAILY_SALARY * 0.8
        return max(0.0, min(budget, bid))

    prev_bids = []
    named_prev = {}
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid')
        if b is not None:
            prev_bids.append(float(b))
            named_prev[agent_id] = float(b)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]
    elif len(prev_bids) == 1:
        second_prev = prev_bids[int(0)]

    eric_bid = named_prev.get('Eric', 0.0)
    cindy_bid = named_prev.get('Cindy', 0.0)

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        target = max(DAILY_SALARY * 0.95, eric_bid + 2.0)
        if tight_supply:
            target = max(target, second_prev + 2.0)
        return max(0.0, min(budget, target))

    if hp <= 4 or no_water >= 1:
        if tight_supply:
            target = max(DAILY_SALARY * 0.82, eric_bid + 1.5)
        else:
            target = max(DAILY_SALARY * 0.68, min(highest_prev * 0.8, eric_bid + 1.0 if eric_bid > 0 else DAILY_SALARY * 0.68))
        return max(0.0, min(budget, target))

    if ample_supply:
        if cindy_bid >= 100:
            target = DAILY_SALARY * 0.28
        else:
            target = DAILY_SALARY * 0.4
        return max(0.0, min(budget, target))

    if tight_supply:
        if eric_bid > 0:
            target = min(DAILY_SALARY * 0.78, eric_bid + 1.25)
        else:
            target = DAILY_SALARY * 0.62
        return max(0.0, min(budget, target))

    if highest_prev >= 90:
        target = DAILY_SALARY * 0.38
    elif eric_bid >= 75:
        target = DAILY_SALARY * 0.58
    else:
        target = DAILY_SALARY * 0.5

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Extract yesterday's bids from traces
    yesterday_bids = []
    for opp in opponents_status.values():
        prev = opp.get('previous_trace')
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if day == 1 or not yesterday_bids:
        # First day or no data: bid based on supply scarcity
        scarcity_factor = max(0.3, 1.0 - (supply - 15) / 10.0)
        base_bid = DAILY_SALARY * scarcity_factor
        if hp <= 3:
            base_bid = DAILY_SALARY * 0.9
        return min(budget, max(base_bid, 1))

    # Have yesterday bids
    max_prev = max(yesterday_bids)
    # Aggressive threshold: if someone bid very high, they might be desperate or bluffing
    aggressive_threshold = DAILY_SALARY * 0.85

    if max_prev >= aggressive_threshold:
        # Opponents were aggressive; if we are healthy, undercut to save budget
        if hp > 4:
            return min(budget, DAILY_SALARY * 0.4)
        else:
            # Need water badly, match or slightly above
            return min(budget, max(DAILY_SALARY * 0.85, max_prev + 1))
    else:
        # Opponents were moderate; try to outbid slightly
        target = max(DAILY_SALARY * 0.45, max_prev + 1.5)
        if hp <= 2:
            target = max(target, DAILY_SALARY * 0.85)
        return min(budget, target)
